reference_solution:
def count_unplaced_fruits(fruits,baskets):
    available=[True]*len(baskets)
    unplaced=0
    for fruit in fruits:
        for i,capacity in enumerate(baskets):
            if available[i] and capacity>=fruit:
                available[i]=False
                break
        else:unplaced+=1
    return unplaced

